const LE_CREDENTIAL: &str = "EOAE2mCC8e2oNXbXPtiDFMMGrQ6N8iS7ZUAS2fWwqua0";
const ECR_CREDENTIAL: &str = "ECV74hW2vMvUaBbpgbsoTyl79D5pRhyIXTpVXn4tn-bi";
const PUBLISHED_ISSUANCE: &str = "ENf3IEYwYtFmlq5ZzoI-zFzeR7E3ZNRN2YH_0KAFbdJW";
const OTHER_TIMESTAMP: &str = "2021-06-27T21:26:21.233257+00:00";

/// A key state carrying only the fields anchoring reads: identifier, position, and digest.
fn key_state(identifier: &str, sequence_number: u128, digest: &str) -> Result<KeyState, Box<dyn Error>> {
    let document = serde_json::json!({
        "vn": [1, 0],
        "i": identifier,
        "s": format!("{sequence_number:x}"),
        "p": "",
        "d": digest,
        "f": "0",
        "dt": "2023-08-23T15:16:07.553000+00:00",
        "et": "icp",
        "kt": "1",
        "k": ["DAKCxMOuoRzREVHsHCkLilBrUXTvyenBiuM2QtV8BB0C"],
        "nt": "1",
        "n": ["EAKCxMOuoRzREVHsHCkLilBrUXTvyenBiuM2QtV8BB0C"],
        "bt": "0",
        "b": [],
        "c": [],
        "ee": {"s": "0", "d": digest, "br": [], "ba": []},
        "di": "",
    });
    Ok(serde_json::from_value(document)?)
}

/// The (issuer, sequence number, prior digest) each recorded case anchors against.
fn anchor_inputs(name: &str, provenance: &Provenance) -> Option<(String, u128, String)> {
    let issuer = provenance.issuer.clone();
    Some(match name {
        // Both cases at position zero anchor over the credential itself, which is what the
        // pinned mock's own key state carries as its latest digest.
        "pinned_mock_credential" | "distinct_timestamp" => (issuer, 0, provenance.credential.clone()),
        "later_in_the_log" => (issuer, 41, PUBLISHED_ISSUANCE.to_owned()),
        "hexadecimal_sequence_number" => (issuer, 254, PUBLISHED_ISSUANCE.to_owned()),
        "large_sequence_number" => (issuer, 4_294_967_295, PUBLISHED_ISSUANCE.to_owned()),
        _ => return None,
    })
}

/// The (credential, registry, timestamp) each recorded issuance is built from.
fn issuance_inputs(name: &str, provenance: &Provenance) -> Option<(String, String, String)> {
    let registry = provenance.registry.clone();
    Some(match name {
        // The mock credential is issued at two different anchor positions, which changes the
        // anchor and leaves the transaction event identical.
        "pinned_mock_credential" | "large_sequence_number" => {
            (provenance.credential.clone(), registry, provenance.timestamp.clone())
        }
        "later_in_the_log" => (LE_CREDENTIAL.to_owned(), registry, provenance.timestamp.clone()),
        "hexadecimal_sequence_number" => (ECR_CREDENTIAL.to_owned(), registry, provenance.timestamp.clone()),
        "distinct_timestamp" => (provenance.credential.clone(), registry, OTHER_TIMESTAMP.to_owned()),
        _ => return None,
    })
}

/// The (credential, registry, prior, timestamp, position, anchor position) of each revocation.
fn revocation_inputs(name: &str, provenance: &Provenance) -> Option<(String, String, String, u128)> {
    let registry = provenance.registry.clone();
    Some(match name {
        "pinned_mock_credential" => (provenance.credential.clone(), registry, provenance.timestamp.clone(), 1),
        "later_in_the_log" => (LE_CREDENTIAL.to_owned(), registry, provenance.timestamp.clone(), 42),
        "distinct_timestamp" => (ECR_CREDENTIAL.to_owned(), registry, OTHER_TIMESTAMP.to_owned(), 6),
        _ => return None,
    })
}

#[test]
fn the_manifest_matches_the_pinned_reference() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.schema_version, 1);
    assert_eq!(fixture.reference_sha, REFERENCE_SHA);
    assert!(fixture.upstream.contains("WebOfTrust/signify-ts"));
    assert_ne!(fixture.generated_on, "");
    assert!(
        fixture
            .sources
            .iter()
            .any(|source| source.ends_with("credentialing.ts"))
    );
    assert!(fixture.sources.iter().any(|source| source.ends_with("core/utils.ts")));
    assert_ne!(fixture.provenance.note, "");
    assert_eq!(fixture.issuances.len(), 5);
    assert_eq!(fixture.revocations.len(), 3);
    Ok(())
}

#[test]
fn the_ported_expressions_are_the_references_own() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let declarations = &fixture.declarations;

    // The issuance expression, in the field order this port writes.
    let issuance = &declarations.issuance_saidify_expression;
    for (earlier, later) in [
        ("v: versify(", "t: Ilks.iss"),
        ("t: Ilks.iss", "d: ''"),
        ("d: ''", "i: acdc.d"),
        ("i: acdc.d", "s: '0'"),
        ("s: '0'", "ri: args.ri"),
        ("ri: args.ri", "dt: subject.dt"),
    ] {
        let (Some(first), Some(second)) = (issuance.find(earlier), issuance.find(later)) else {
            return Err(format!("{earlier:?} and {later:?} are no longer both in the issuance expression").into());
        };
        assert!(first < second, "{earlier:?} must precede {later:?}");
    }
    // The timestamp is the credential's, not a second clock reading.
    assert!(issuance.contains("dt: subject.dt"));
    assert_ne!(declarations.notes.issuance, "");

    // The revocation literal, which adds exactly one field and fixes the position.
    let revocation = &declarations.revocation_literal;
    for (earlier, later) in [
        ("t: Ilks.rev", "d: ''"),
        ("d: ''", "i: said"),
        ("i: said", "s: '1'"),
        ("s: '1'", "ri: registryId"),
        ("ri: registryId", "p: cred.status.d"),
        ("p: cred.status.d", "dt: dt"),
    ] {
        let (Some(first), Some(second)) = (revocation.find(earlier), revocation.find(later)) else {
            return Err(format!("{earlier:?} and {later:?} are no longer both in the revocation literal").into());
        };
        assert!(first < second, "{earlier:?} must precede {later:?}");
    }
    assert!(declarations.revocation_saidify_expression.contains("_rev"));
    assert_ne!(declarations.notes.revocation, "");

    // Both anchors are the same interaction, sealing one `{i, s, d}` at the next position.
    for expression in [
        &declarations.issuance_anchor_expression,
        &declarations.revocation_anchor_expression,
    ] {
        assert!(expression.contains("sn: sn + 1"), "{expression}");
        assert!(expression.contains("interact("), "{expression}");
    }
    assert!(declarations.issuance_anchor_expression.contains("i: iss.i"));
    assert_ne!(declarations.notes.issuance_anchor, "");

    // Both serializers, whose framing this port makes an argument.
    assert!(declarations.acdc_attachment_body.contains("SealSourceTriples"));
    assert!(declarations.iss_attachment_body.contains("SealSourceCouples"));
    assert!(declarations.iss_attachment_body.contains("AttachedMaterialQuadlets"));
    assert!(!declarations.acdc_attachment_body.contains("AttachedMaterialQuadlets"));
    assert_ne!(declarations.notes.attachments, "");

    // The three constants this port hard-codes, read from the reference rather than assumed.
    assert_eq!(
        declarations.keri_version_string,
        signify_acdc::transaction::UNSIZED_VERSION_STRING
    );
    assert_eq!(declarations.issuance_ilk, "iss");
    assert_eq!(declarations.revocation_ilk, "rev");
    assert_ne!(declarations.revocation_registry_fallback, "");
    Ok(())
}

#[test]
fn every_issuance_matches_byte_for_byte() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    for (name, expected) in &fixture.issuances {
        let (credential, registry, timestamp) =
            issuance_inputs(name, &fixture.provenance).ok_or_else(|| format!("unknown issuance case {name:?}"))?;
        let issuance = IssuanceEvent::new(
            Said::from_qb64(&credential)?,
            RegistryIdentifier::from_qb64(&registry)?,
            timestamp.parse::<Timestamp>()?,
        )?;

        assert!(!expected.note.is_empty(), "{name}");
        assert_eq!(issuance.raw(), expected.iss_raw.as_bytes(), "{name}");
        assert_eq!(issuance.said().qb64()?, expected.iss_said, "{name}");
        assert_eq!(issuance.raw().len(), expected.iss_size, "{name}");
        assert!(expected.reference_verifies, "{name}");
        issuance
            .said()
            .verify(issuance.sad(), DEFAULT_SAID_LABEL, SaidVerification::strict())?;

        // The anchoring interaction, at the issuer's next position over its current digest.
        let (issuer, sequence_number, prior) =
            anchor_inputs(name, &fixture.provenance).ok_or_else(|| format!("unknown anchor case {name:?}"))?;
        let state = key_state(&issuer, sequence_number, &prior)?;
        let anchor = anchor_event(&state, &issuance.seal())?;
        assert_eq!(anchor.raw(), expected.anchor_raw.as_bytes(), "{name}");
        assert_eq!(anchor.said().qb64()?, expected.anchor_said, "{name}");
        assert_eq!(anchor.raw().len(), expected.anchor_size, "{name}");

        // The recorded seal, compared field by field rather than as text.
        let recorded = expected.anchor_seal.first().ok_or("no recorded seal")?;
        let seal = issuance.seal().to_sad()?;
        assert_eq!(seal.get_text("i"), recorded.get("i").map(String::as_str), "{name}");
        assert_eq!(seal.get_text("s"), recorded.get("s").map(String::as_str), "{name}");
        assert_eq!(seal.get_text("d"), recorded.get("d").map(String::as_str), "{name}");

        // Both attachments.
        assert_eq!(
            core::str::from_utf8(&issuance.credential_attachment()?)?,
            expected.credential_attachment,
            "{name}"
        );
        let couple = SealSourceCouple::new(anchor.sequence_number().into(), anchor.said());
        assert_eq!(
            core::str::from_utf8(&couple.attachment(AttachmentFraming::Pipelined)?)?,
            expected.issuance_attachment,
            "{name}"
        );
    }
    Ok(())
}

#[test]
fn every_revocation_matches_byte_for_byte() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    for (name, expected) in &fixture.revocations {
        let (credential, registry, timestamp, anchor_position) =
            revocation_inputs(name, &fixture.provenance).ok_or_else(|| format!("unknown revocation case {name:?}"))?;
        let revocation = RevocationEventBuilder::new(
            Said::from_qb64(&credential)?,
            RegistryIdentifier::from_qb64(&registry)?,
            Said::from_qb64(PUBLISHED_ISSUANCE)?,
            timestamp.parse::<Timestamp>()?,
        )
        .build()?;

        assert!(!expected.note.is_empty(), "{name}");
        assert_eq!(revocation.raw(), expected.rev_raw.as_bytes(), "{name}");
        assert_eq!(revocation.said().qb64()?, expected.rev_said, "{name}");
        assert_eq!(revocation.raw().len(), expected.rev_size, "{name}");
        assert!(expected.reference_verifies, "{name}");
        revocation
            .said()
            .verify(revocation.sad(), DEFAULT_SAID_LABEL, SaidVerification::strict())?;

        let state = key_state(&fixture.provenance.issuer, anchor_position, PUBLISHED_ISSUANCE)?;
        let anchor = anchor_event(&state, &revocation.seal())?;
        assert_eq!(anchor.raw(), expected.anchor_raw.as_bytes(), "{name}");
        assert_eq!(anchor.said().qb64()?, expected.anchor_said, "{name}");
        assert_eq!(anchor.raw().len(), expected.anchor_size, "{name}");

        let recorded = expected.anchor_seal.first().ok_or("no recorded seal")?;
        let seal = revocation.seal().to_sad()?;
        assert_eq!(seal.get_text("i"), recorded.get("i").map(String::as_str), "{name}");
        assert_eq!(seal.get_text("s"), recorded.get("s").map(String::as_str), "{name}");
        assert_eq!(seal.get_text("d"), recorded.get("d").map(String::as_str), "{name}");
    }
    Ok(())
}

#[test]
fn the_artifacts_the_pinned_test_suite_publishes_reproduce() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let pinned = &fixture.pinned_artifacts;

    // The generator proved both against the reference; the fixture carries the proof.
    assert!(pinned.iss_said_matches_published);
    assert!(pinned.attachments_appear_in_grant);
    assert!(pinned.anchor_seals_empty_object);
    assert_ne!(pinned.note, "");
    assert!(pinned.grant_attachment.starts_with("-LAg4AACA-e-acdc"));

    // And this port rebuilds the same issuance and the same attachment from the same inputs.
    let issuance = IssuanceEvent::new(
        Said::from_qb64(&fixture.provenance.credential)?,
        RegistryIdentifier::from_qb64(&fixture.provenance.registry)?,
        fixture.provenance.timestamp.parse::<Timestamp>()?,
    )?;
    assert_eq!(issuance.raw(), pinned.iss_raw.as_bytes());
    assert_eq!(issuance.said().qb64()?, pinned.iss_said);
    assert_eq!(issuance.said().qb64()?, PUBLISHED_ISSUANCE);
    assert_eq!(
        core::str::from_utf8(&issuance.credential_attachment()?)?,
        pinned.credential_attachment
    );
    assert!(pinned.grant_attachment.contains(&pinned.credential_attachment));

    // The pinned test's own anchor seals `[{}]` rather than the transaction event, so what this
    // port reproduces from it is the couple naming it, which is the attachment 6.3 will embed.
    let anchor = SerializedEvent::parse(pinned.anchor_raw.as_bytes())?;
    let couple = SealSourceCouple::new(1_u128.into(), Said::from_qb64(&pinned.anchor_said)?);
    assert_eq!(
        core::str::from_utf8(&couple.attachment(AttachmentFraming::Pipelined)?)?,
        pinned.issuance_attachment
    );
    assert!(pinned.grant_attachment.contains(&pinned.issuance_attachment));
    assert_eq!(anchor.said(), Some(pinned.anchor_said.as_str()));
    Ok(())
}

#[test]
fn both_serializer_vectors_the_reference_publishes_reproduce() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let pinned = &fixture.pinned_serializers;

    // The reference asserts both of these strings directly in `test/core/utils.test.ts`.
    assert_eq!(pinned.published_in_test.len(), 2);
    assert!(pinned.published_in_test.contains(&pinned.iss_attachment));
    assert!(pinned.published_in_test.contains(&pinned.acdc_attachment));
    assert_ne!(pinned.note, "");

    // Neither input is a message this port would accept as one: both write their version string
    // after another field, which Roadmap 3.2's `SerializedEvent` refuses and the reference's
    // `Serder` does not. They are read as ordered data instead, which is all the serializers use.
    let iss_input = Sad::from_json_bytes(pinned.iss_attachment_input.as_bytes())?;
    assert_ne!(iss_input.first_label(), Some("v"));

    // The couple case: its input carries no sequence number at all, which the reference reads as
    // zero. Rebuilding it here means naming that zero explicitly.
    let iss_said = Said::from_qb64(iss_input.get_text("d").ok_or("no said")?)?;
    assert!(!iss_input.contains("s"));
    let couple = SealSourceCouple::new(0_u128.into(), iss_said);
    assert_eq!(
        core::str::from_utf8(&couple.attachment(AttachmentFraming::Pipelined)?)?,
        pinned.iss_attachment
    );

    // The triple case: an ACDC document whose issuance seal names it at position zero. The
    // reference reads the triple's three values off the event it is handed, which is exactly what
    // a `TransactionSeal` holds.
    let acdc_input = Sad::from_json_bytes(pinned.acdc_attachment_input.as_bytes())?;
    assert_ne!(acdc_input.first_label(), Some("v"));
    let seal = TransactionSeal::new(
        Said::from_qb64(acdc_input.get_text("i").ok_or("no identifier")?)?,
        0,
        Said::from_qb64(acdc_input.get_text("d").ok_or("no said")?)?,
    );
    let triple = signify_keri::attachment::SealSourceTriple::new(
        signify_keri::prefix::IdentifierPrefix::SelfAddressing(seal.credential()),
        seal.sequence_number().into(),
        seal.said(),
    );
    assert_eq!(
        core::str::from_utf8(&triple.attachment(AttachmentFraming::Plain)?)?,
        pinned.acdc_attachment
    );
    Ok(())
}

#[test]
fn every_recorded_divergence_names_its_reason_and_its_rust_decision() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let quirks = &fixture.reference_quirks;
    let pairs: [(&str, &str); 9] = [
        (
            &quirks.revocation_sequence_number_is_always_one.note,
            &quirks.revocation_sequence_number_is_always_one.rust_decision,
        ),
        (
            &quirks.revocation_reads_the_registry_from_ri_or_rd.note,
            &quirks.revocation_reads_the_registry_from_ri_or_rd.rust_decision,
        ),
        (
            &quirks.revocation_timestamp_defaults_to_the_clock.note,
            &quirks.revocation_timestamp_defaults_to_the_clock.rust_decision,
        ),
        (
            &quirks.issuance_reuses_the_credential_timestamp.note,
            &quirks.issuance_reuses_the_credential_timestamp.rust_decision,
        ),
        (
            &quirks.acdc_attachment_is_passed_the_issuance_event.note,
            &quirks.acdc_attachment_is_passed_the_issuance_event.rust_decision,
        ),
        (
            &quirks.missing_sequence_number_reads_as_zero.note,
            &quirks.missing_sequence_number_reads_as_zero.rust_decision,
        ),
        (
            &quirks.establishment_only_is_unimplemented.note,
            &quirks.establishment_only_is_unimplemented.rust_decision,
        ),
        (
            &quirks.backed_transaction_events_have_no_builder.note,
            &quirks.backed_transaction_events_have_no_builder.rust_decision,
        ),
        (
            &quirks.revocation_prior_comes_from_the_server.note,
            &quirks.revocation_prior_comes_from_the_server.rust_decision,
        ),
    ];
    for (index, (note, decision)) in pairs.iter().enumerate() {
        assert!(!note.is_empty(), "divergence {index} records no reference behaviour");
        assert!(!decision.is_empty(), "divergence {index} records no Rust decision");
    }
    Ok(())
}

#[test]
fn every_reference_quirk_holds_and_the_divergence_is_deliberate() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let quirks = &fixture.reference_quirks;
    let credential = Said::from_qb64(&fixture.provenance.credential)?;
    let registry = RegistryIdentifier::from_qb64(&fixture.provenance.registry)?;
    let prior = Said::from_qb64(PUBLISHED_ISSUANCE)?;
    let timestamp: Timestamp = fixture.provenance.timestamp.parse()?;

    // 1. The revocation position is a literal `'1'` upstream; here it defaults to one and can be
    //    anything, which a backed registry's log needs.
    assert_eq!(
        quirks.revocation_sequence_number_is_always_one.literal_sequence_number,
        "1"
    );
    let default = RevocationEventBuilder::new(credential, registry.clone(), prior, timestamp.clone()).build()?;
    assert_eq!(default.sad().get_text("s"), Some("1"));
    let moved = RevocationEventBuilder::new(credential, registry.clone(), prior, timestamp.clone())
        .sequence_number(4)
        .build()?;
    assert_eq!(moved.sad().get_text("s"), Some("4"));

    // 2. The `rd` fallback is unreachable from a credential this port builds, which always writes
    //    `ri`; the expression is recorded rather than reproduced.
    let fallback = &quirks.revocation_reads_the_registry_from_ri_or_rd.fallback_expression;
    assert!(fallback.contains("'ri' in cred.sad"));
    assert!(fallback.contains("'rd' in cred.sad"));

    // 3. The revocation timestamp is a clock reading upstream and a required input here.
    let clock = &quirks.revocation_timestamp_defaults_to_the_clock.expression;
    assert!(clock.contains("toISOString"));
    assert!(clock.contains("000+00:00"));

    // 4. The issuance borrows the credential's timestamp rather than reading a clock twice.
    let reused = &quirks.issuance_reuses_the_credential_timestamp;
    assert!(reused.identical);
    assert_eq!(reused.credential_timestamp, reused.issuance_timestamp);
    assert_eq!(reused.credential_timestamp, fixture.provenance.timestamp);

    // 5. The triple serializer is handed the issuance event despite its parameter name.
    let triple = &quirks.acdc_attachment_is_passed_the_issuance_event;
    assert!(triple.triple.starts_with("-IAB"));
    assert!(triple.triple.contains(&fixture.provenance.credential));
    assert!(triple.triple.contains(PUBLISHED_ISSUANCE));

    // 6. A transaction event with no `s` field reads as position zero upstream; here a sequence
    //    number is a `u128` on a typed event and is never read back out of an untyped map.
    let missing = &quirks.missing_sequence_number_reads_as_zero;
    assert!(!missing.input.contains("\"s\""));
    assert!(missing.attachment.starts_with("-VAS-GAB0AAAAAAAAAAAAAAAAAAAAAAA"));

    // 7. An establishment-only issuer throws upstream and is a typed refusal here.
    let establishment = &quirks.establishment_only_is_unimplemented;
    assert_eq!(establishment.scan.needle, "Establishment only not implemented");
    assert_eq!(establishment.scan.total, 2);
    assert_eq!(
        establishment.scan.files.first().map(|hit| hit.file.as_str()),
        Some("src/keri/app/credentialing.ts")
    );
    assert_eq!(establishment.scan.files.first().map(|hit| hit.count), Some(2));
    assert!(establishment.scan.scanned_files > 100);

    let mut state = key_state(&fixture.provenance.issuer, 0, &fixture.provenance.credential)?;
    state.configuration = vec!["EO".to_owned()];
    assert!(is_establishment_only(&state));
    let issuance = IssuanceEvent::new(credential, registry, timestamp)?;
    assert!(matches!(
        anchor_event(&state, &issuance.seal()),
        Err(TransactionError::EstablishmentOnlyIssuer { trait_code: "EO" })
    ));

    // 8. `bis` and `brv` are declared in the ilk table and constructed nowhere.
    let backed = &quirks.backed_transaction_events_have_no_builder;
    assert_eq!(backed.scan_bis.total, 0);
    assert_eq!(backed.scan_brv.total, 0);
    assert!(backed.scan_bis.files.is_empty());
    assert!(backed.scan_brv.files.is_empty());
    assert!(backed.scan_bis.scanned_files > 100);

    // 9. The revocation's prior digest comes from the server upstream and is an input here.
    assert!(
        quirks
            .revocation_prior_comes_from_the_server
            .expression
            .contains("cred.status.d")
    );
    Ok(())
}
